/** Data generated by scripts/generate-benchmarks.mjs (static/benchmarks/data.json and the props of the pages). */

export type Tier = 'micro' | 'app' | 'infra';

export interface BenchTask {
    /** `<package>/<suite>@v<version>/<task>` */
    id: string;
    package: string;
    suite: string;
    task: string;
    tier: Tier;
    baseline: string | null;
}

/** `[version, p50 in ns, ratio to the reference, heap bytes]` */
export type Point = [string, number, number | null, number | null];

export interface BenchEnvironment {
    /** `<fingerprint>/node-<major>` */
    id: string;
    fingerprint: string;
    node: number;
}

export interface BenchData {
    schema: number;
    /** From the oldest to the newest. */
    releases: string[];
    /** The reference environment first. */
    environments: BenchEnvironment[];
    tasks: BenchTask[];
    values: Record<string, Record<string, Point[]>>;
}

export type Classification = 'improvement' | 'stable' | 'warning' | 'regression' | 'new' | 'none';

export interface ReportRow {
    id: string;
    suite: string;
    task: string;
    tier: Tier;
    p50: number;
    rme: number;
    ops: number;
    ratio: number | null;
    baseline: string | null;
    /** The task is the reference without the framework of another task. */
    reference: boolean;
    heap: number | null;
    previousP50: number | null;
    delta: number | null;
    classification: Classification;
}

export interface ReportEnvironment {
    id: string;
    kind: 'release' | 'backfill';
    runId: string;
    sha: string | null;
    previous: string | null;
    summary: Record<'improvement' | 'stable' | 'warning' | 'regression' | 'new', number>;
    errors: { suite: string; message: string }[];
    env: { fingerprint: string; node: string; v8: string; os: string; cpu: string; cores: number; memoryGb: number; tinybench: string };
    packages: { name: string; rows: ReportRow[] }[];
}

export interface ReleaseSummary {
    version: string;
    kind: 'release' | 'backfill';
    environments: string[];
    summary: ReportEnvironment['summary'];
    previous: string | null;
}
